import { encoderSource } from "./encoder-codegen.js";
import { Schema, openSchema } from "../runtime/schema.js";
import { verifySchema } from "../runtime/verify.js";
import { TypeView } from "../runtime/reflection.js";
import { Kind, NO_INDEX as N, width, readWord, Region } from "../format.js";
/** Emit typed accessors from the compiled image. No source layout algorithm is repeated here. */
export function generateTypescript(bytes: Uint8Array): string {
  const s = openSchema(bytes);
  verifySchema(s);
  const lines: string[] = [
    "// Generated by fass from the exact compiled binary schema.",
    "import {Schema,Document,RecordView,ValueView,ArrayView,MapView,Span,Code,Region,fail,openCompiledInto,compiledSpanInto,compiledString24Into,compiledReference,compiledString,borrowedU32,utf8Length,writeUtf8Into,compiledWriteSpan,measure,encodeInto,encode} from 'fass';",
    `export const schemaBytes=new Uint8Array([${[...bytes].join(",")}]);`,
    `export const schema=new Schema().open(schemaBytes);`,
    `export const ROOT_LAYOUT=${s.root};`,
  ];
  const read = (k: number, at: string, bit = 0) =>
    k === 11
      ? `!!(this.doc.bytes[${at}] & ${1 << bit})`
      : `this.doc.dv.${["", "getInt8", "getUint8", "getInt16", "getUint16", "getInt32", "getUint32", "getBigInt64", "getBigUint64", "getFloat32", "getFloat64"][k]}(${at}${width(k) > 1 ? ",true" : ""})`;
  const type = (k: number) =>
    k === 11 ? "boolean" : k === 7 || k === 8 ? "bigint" : "number";
  function check(k: number, value: string, rule: number = N): string {
    const w = width(k),
      signed = k % 2 === 1,
      b = w * 8;
    let code = "";
    if (k === 11)
      code = `if(typeof ${value}!=='boolean')fail(Code.TypeMismatch,Region.Data);`;
    else if (k >= 9)
      code = `if(typeof ${value}!=='number')fail(Code.TypeMismatch,Region.Data);`;
    else {
      const lo = signed ? -(1n << BigInt(b - 1)) : 0n,
        hi = signed ? (1n << BigInt(b - 1)) - 1n : (1n << BigInt(b)) - 1n,
        suffix = w === 8 ? "n" : "";
      code = `if(${w === 8 ? `typeof ${value}!=='bigint'` : `!Number.isInteger(${value})`}||${value}<${lo}${suffix}||${value}>${hi}${suffix})fail(Code.BoundExceeded,Region.Data);`;
    }
    if (rule !== N) {
      const r = s.entry(7, rule),
        numeric = (n: bigint) =>
          `${signed ? BigInt.asIntN(b, n) : n}${w === 8 ? "n" : ""}`;
      if (s.u8(r) === 1)
        code += `if(${value}<${numeric(readWord(s.bytes, r + 16, 8, Region.Schema))}||${value}>${numeric(readWord(s.bytes, r + 24, 8, Region.Schema))})fail(Code.BoundExceeded,Region.Data);`;
      else {
        const values = Array.from({ length: s.u32(r + 8) }, (_, i) =>
          numeric(
            readWord(s.bytes, s.entry(8, s.u32(r + 4) + i), 8, Region.Schema),
          ),
        );
        code += `if(!(${values.map((n) => `${value}===${n}`).join("||")}))fail(Code.BoundExceeded,Region.Data);`;
      }
    }
    return code;
  }
  function store(k: number, at: string, value: string, bit = 0): string {
    if (k === 11)
      return `this.doc.bytes[${at}]=(this.doc.bytes[${at}] & ~${1 << bit})|(${value}?${1 << bit}:0);`;
    return `this.doc.dv.${["", "setInt8", "setUint8", "setInt16", "setUint16", "setInt32", "setUint32", "setBigInt64", "setBigUint64", "setFloat32", "setFloat64"][k]}(${at},${value}${width(k) > 1 ? ",true" : ""});`;
  }
  const span = (p: number, at: string, out: string) =>
    s.u8(p) === 12 &&
    s.u8(p + 1) === 4 &&
    s.u8(p + 2) === 24 &&
    s.u8(p + 3) === 8
      ? `compiledString24Into(this.doc,${at},${s.u32(p + 16)},${out})`
      : `compiledSpanInto(this.doc,${at},${s.u8(p + 1)},${s.u8(p + 2)},${s.u8(p + 3)},${s.u32(p + 16)},${s.u8(p) === 12 ? 1 : s.u32(p + 12)},${!!(s.u32(p + 4) & 1)},${out})`;
  for (let i = 0; i < s.count(1); i++) {
    const l = s.layout(i),
      first = s.u32(l + 4),
      n = s.u32(l + 8),
      td = new TypeView(s, s.u32(l + 12));
    lines.push(
      `export class Layout${i} {doc!:Document;anchor=0;readOnly=false;private value=new ValueView();private record=new RecordView();private span=new Span();`,
      `_bind(doc:Document,anchor:number,readOnly:boolean):this{this.doc=doc;this.anchor=anchor;this.readOnly=readOnly;return this;}`,
    );
    if (i === s.root)
      lines.push(
        `private owner=new Document();open(bytes:Uint8Array,writable=false):this{openCompiledInto(bytes,schema,${s.u32(l)},writable,this.owner);return this._bind(this.owner,0,false);}`,
      );
    lines.push(
      `private field(slot:number):ValueView{return this.record.bind(this.doc,${i},this.anchor,this.readOnly).atSlotInto(slot,this.value);}`,
    );
    for (let slot = 0; slot < n; slot++) {
      const fi = first + slot,
        a = s.access(fi),
        link = s.entry(3, fi),
        k = s.u8(a + 4),
        flags = s.u8(a + 5),
        target = s.u32(link),
        presence = s.u32(link + 4),
        name = td.field(slot).name(),
        method = "get" + name[0].toUpperCase() + name.slice(1),
        setter = "set" + name[0].toUpperCase() + name.slice(1),
        at = `this.anchor+${s.u32(a)}`;
      const guard =
        presence === N
          ? ""
          : (() => {
              const p = s.entry(6, presence);
              return `if(!(this.doc.bytes[this.anchor+${s.u32(p)}]&${s.u8(p + 4)}))fail(Code.Absent,Region.Data,this.anchor+${s.u32(p)});`;
            })();
      if (k <= 11) {
        const p = s.plan(target);
        lines.push(
          `${method}():${type(k)}{${guard}return ${read(k, at, s.u8(a + 6))};}`,
        );
        if (!(flags & 2))
          lines.push(
            `${setter}(value:${type(k)}):void{${guard}if(!this.doc.writable||this.readOnly)fail(Code.ReadOnly,Region.Data);${check(k, "value", s.u32(p + 28))}${store(k, at, "value", s.u8(a + 6))}}`,
          );
      } else if (k === 15 || k === 16) {
        const child = s.layout(target),
          anchor =
            k === 15
              ? "this.anchor"
              : `compiledReference(this.doc,${at},${flags >> 4},${s.u8(a + 6)},${s.u32(child)})`;
        lines.push(
          `${method}Into(out:Layout${target}):Layout${target}{${guard}return out._bind(this.doc,${anchor},this.readOnly||${!!(flags & 2)});}`,
        );
      } else if (k === 12) {
        const p = s.plan(target);
        lines.push(
          `${method}BytesInto(out:Span):Span{${guard}return ${span(p, at, "out")};}`,
          `${method}():string{return compiledString(this.doc,this.${method}BytesInto(this.span));}`,
        );
      } else if (k === 13 || k === 14) {
        const p = s.plan(target);
        lines.push(
          `${method}Into(out:ArrayPlan${target}):ArrayPlan${target}{${guard}${k === 13 ? span(p, at, "out") + ";" : `out.offset=${at};out.count=${s.u32(p + 16)};`}out.doc=this.doc;out.readOnly=this.readOnly||${!!(flags & 2)};return out;}`,
        );
      } else
        lines.push(
          `${method}Into(out:MapView):MapView{return out.bind(this.field(${slot}));}`,
        );
    }
    lines.push("}");
  }
  for (let i = 0; i < s.count(4); i++) {
    const p = s.plan(i),
      kind = s.u8(p);
    if (kind !== 13 && kind !== 14) continue;
    const child = s.u32(p + 20),
      cp = s.plan(child),
      k = s.u8(cp),
      stride = s.u32(p + 12),
      packed = !!(s.u32(p + 4) & 1),
      pos = packed
        ? "this.offset+Math.floor(index/8)"
        : `this.offset+index*${stride}`,
      indexCheck =
        "if(!Number.isInteger(index)||index<0||index>=this.count)fail(Code.BoundExceeded,Region.Data,this.offset,index);";
    lines.push(
      `export class ArrayPlan${i} extends Span {doc!:Document;readOnly=false;private span=new Span();private value=new ValueView();`,
    );
    if (k <= 11) {
      let expr = read(k, pos);
      if (packed)
        expr = `!!(this.doc.bytes[this.offset+Math.floor(index/8)]&(1<<(index%8)))`;
      lines.push(`get(index:number):${type(k)}{${indexCheck}return ${expr};}`);
      const st = packed
        ? "const at=this.offset+Math.floor(index/8),mask=1<<(index%8);this.doc.bytes[at]=(this.doc.bytes[at]&~mask)|(value?mask:0);"
        : store(k, pos, "value");
      lines.push(
        `set(index:number,value:${type(k)}):void{${indexCheck}if(this.readOnly||!this.doc.writable)fail(Code.ReadOnly,Region.Data);${check(k, "value", s.u32(cp + 28))}${st}}`,
      );
      if (k === Kind.U32)
        lines.push(
          "borrow():Uint32Array{if(this.readOnly)fail(Code.ReadOnly,Region.Data);return borrowedU32(this.doc,this.offset,this.count);}",
        );
    } else if (k === 15 || k === 16) {
      const target = s.u32(cp + 20),
        l = s.layout(target),
        at =
          k === 15
            ? pos
            : `compiledReference(this.doc,${pos},${s.u8(cp + 1)},${s.u8(cp + 2)},${s.u32(l)})`;
      lines.push(
        `atInto(index:number,out:Layout${target}):Layout${target}{${indexCheck}return out._bind(this.doc,${at},this.readOnly);}`,
      );
    } else if (k === 12)
      lines.push(
        `bytesInto(index:number,out:Span):Span{${indexCheck}return ${span(cp, pos, "out")};}`,
        `get(index:number):string{return compiledString(this.doc,this.bytesInto(index,this.span));}`,
      );
    else if (k === 13 || k === 14)
      lines.push(
        `atInto(index:number,out:ArrayPlan${child}):ArrayPlan${child}{${indexCheck}${k === 13 ? span(cp, pos, "out") + ";" : `out.offset=${pos};out.count=${s.u32(cp + 16)};`}out.doc=this.doc;out.readOnly=this.readOnly;return out;}`,
      );
    else
      lines.push(
        `atInto(index:number,out:MapView):MapView{${indexCheck}return out.bind(this.value.bindPlan(this.doc,${child},${pos},this.readOnly));}`,
      );

    if (k === Kind.Record) {
      const layout = s.u32(cp + 20),
        l = s.layout(layout),
        td = new TypeView(s, s.u32(l + 12));
      for (let slot = 0; slot < s.u32(l + 8); slot++) {
        const fi = s.u32(l + 4) + slot,
          a = s.access(fi),
          ck = s.u8(a + 4);
        if (ck > 11) continue;
        const link = s.entry(3, fi),
          presence = s.u32(link + 4),
          name = td.field(slot).name(),
          method = "get" + name[0].toUpperCase() + name.slice(1),
          at = `this.offset+index*${stride}+${s.u32(a)}`,
          guard =
            presence === N
              ? ""
              : (() => {
                  const pr = s.entry(6, presence);
                  return `if(!(this.doc.bytes[this.offset+index*${stride}+${s.u32(pr)}]&${s.u8(pr + 4)}))fail(Code.Absent,Region.Data);`;
                })();
        lines.push(
          `${method}(index:number):${type(ck)}{${indexCheck}${guard}return ${read(ck, at, s.u8(a + 6))};}`,
        );
      }
    }

    lines.push("}");
  }
  lines.push(`export {Layout${s.root} as RootView};`);
  const names = new Set<string>(["Root"]);
  for (let i = 0; i < s.count(1); i++) {
    const l = s.layout(i);
    if (s.u32(l + 24) !== 1) continue;
    const name = new TypeView(s, s.u32(l + 12)).name();
    if (!/^[A-Za-z_]\w*$/.test(name) || names.has(name)) continue;
    names.add(name);
    lines.push(`export {Layout${i} as ${name}View};`);
  }
  return lines.join("\n") + "\n" + encoderSource(s);
}
